static inline float sentrovaDnnRelu(float x) {
  return x > 0.0f ? x : 0.0f;
}

static inline float sentrovaDnnSigmoid(float x) {
  if (x >= 0.0f) {
    float e = expf(-x);
    return 1.0f / (1.0f + e);
  } else {
    float e = expf(x);
    return e / (1.0f + e);
  }
}

static inline float sentrovaDnnPredictFallProbability(const float* input) {
  float x[60];
  for (int i = 0; i < 60; ++i) {
    float v = input[i];
    if (!isfinite(v)) v = SENTROVA_DNN_IMPUTER_MEDIANS[i];
    float scale = SENTROVA_DNN_SCALER_SCALE[i];
    if (!isfinite(scale) || fabsf(scale) < 1e-12f) scale = 1.0f;
    x[i] = (v - SENTROVA_DNN_SCALER_MEAN[i]) / scale;
  }

  float h1[64] = {0};
  for (int j=0;j<64;j++) {
    float s = SENTROVA_DNN_B1[j];
    for (int i=0;i<60;i++) s += x[i] * SENTROVA_DNN_W1[i*64+j];
    h1[j] = sentrovaDnnRelu(s);
  }

  float h2[32] = {0};
  for (int j=0;j<32;j++) {
    float s = SENTROVA_DNN_B2[j];
    for (int i=0;i<64;i++) s += h1[i] * SENTROVA_DNN_W2[i*32+j];
    h2[j] = sentrovaDnnRelu(s);
  }

  float h3[16] = {0};
  for (int j=0;j<16;j++) {
    float s = SENTROVA_DNN_B3[j];
    for (int i=0;i<32;i++) s += h2[i] * SENTROVA_DNN_W3[i*16+j];
    h3[j] = sentrovaDnnRelu(s);
  }

  float out = SENTROVA_DNN_B4[0];
  for (int i=0;i<16;i++) out += h3[i] * SENTROVA_DNN_W4[i];
  return sentrovaDnnSigmoid(out);
}

static inline bool sentrovaDnnPredictFall(const float* input) {
  return sentrovaDnnPredictFallProbability(input) >= SENTROVA_DNN_THRESHOLD;
}
